class MappingStore:
    def __init__(self, ttl: int = 3600):
        self._store = {}
        self._timestamps = {}
        self._ttl = ttl
        self._lock = threading.Lock()
    def get_mapping(self, session_id: str) -> dict:
        with self._lock:
            self._cleanup(session_id)
            return self._store.setdefault(session_id, {})

